/** Gameplay owner of peerless identities, isolated planning, bounded motors and ordinary action commits. */
public final class HostedBotDirector implements AutoCloseable {
    private final class Runtime {
        final HostedBotRoster.Member member;final SourceRandom random;final HostedBotMotor hosted;final BotPerception.Observer observer;
        BotProfile profile;boolean wasAlive=true;int lives=3;double lastMotor;
        Runtime(HostedBotRoster.Member member,BotProfile profile){this.member=member;this.profile=profile;random=new SourceRandom(randomRoster.below31()+0L);hosted=new HostedBotMotor(roster,member,snapshots,profile,random,budget,action->pending.put(member.player().id(),action));observer=new BotPerception.Observer(actor(member.player()),member.generation(),profile,match.monotonic()+runtime.size()/settings.perceptionHz()/Math.max(1,maxBots));}
        PlayerLife player(){return member.player();}BotMotor motor(){return hosted.motor();}
    }
    private final Thread owner=Thread.currentThread();private final ApplicationHost host;private final Supplier<StandardMatchDomain> current;private final BotSettings settings;private final Path maps;
    private final List<BotPrefabPolicy.Geometry> geometry;private final DoubleSupplier workClock;private final BotWorker worker;private final HostedBotRoster roster;private final BotProfileFactory profiles;private final SourceRandom randomRoster;private final BotBanter banter;private final BotSkillBalancer skill=new BotSkillBalancer();private BotStimulusBus hearing=new BotStimulusBus();private final BotMotor.Budget budget=new BotMotor.Budget();
    private final LinkedHashMap<Integer,Runtime> runtime=new LinkedHashMap<>();private final LinkedHashMap<Integer,HostedBotMotor.Staged> pending=new LinkedHashMap<>();private StandardMatchDomain match;private MutableWorld world;private HostedBotSnapshots snapshots;private HostedBotObjectives objectives;private HostedBotHorde horde;private BotPerception perception;private BotPopulation population;private MutableWorld.RemovalLease changes,lights;private MapSnapshot mapSnapshot;
    private long mapEpoch,modeEpoch,topology,frameId;private Integer reconnectCount;private int motorPhase,games,cleanSlates;private double nextPopulation;private boolean started,closed;private String populationMode,difficulty;private int fillTarget,maxBots;private boolean debug;
    public HostedBotDirector(ApplicationHost host,Supplier<StandardMatchDomain> current,BotSettings settings,Path maps,List<BotPrefabPolicy.Geometry> geometry,DoubleSupplier workClock){this(host,current,settings,maps,geometry,workClock,worker(settings,workClock));}
    private static BotWorker worker(BotSettings settings,DoubleSupplier clock){BiConsumer<String,Throwable> failure=(name,error)->System.getLogger("bots").log(System.Logger.Level.ERROR,name,error);return settings.worker().equals("process")?BotWorker.process(settings.decisionHz(),settings.pathRequests(),clock,failure):BotWorker.simple(settings.decisionHz(),settings.pathRequests(),clock,failure);}
    /** Worker injection keeps the live owner independently exercisable without a native client. */
    public HostedBotDirector(ApplicationHost host,Supplier<StandardMatchDomain> current,BotSettings settings,Path maps,List<BotPrefabPolicy.Geometry> geometry,DoubleSupplier workClock,BotWorker worker){this.host=Objects.requireNonNull(host);this.current=Objects.requireNonNull(current);this.settings=Objects.requireNonNull(settings);this.maps=maps;this.geometry=List.copyOf(geometry);this.workClock=Objects.requireNonNull(workClock);this.worker=Objects.requireNonNull(worker);populationMode=settings.populationMode();difficulty=settings.difficulty();fillTarget=settings.fillTarget();maxBots=settings.maxBots();debug=settings.debug();roster=new HostedBotRoster(host,current);profiles=new BotProfileFactory(settings.seed(),15-settings.namePrefix().length());randomRoster=new SourceRandom(settings.seed());banter=new BotBanter(settings.seed());host.botRoomForHuman(this::makeRoomForHuman);}
    private void owned(){if(Thread.currentThread()!=owner||closed)throw new IllegalStateException("Bot director outside active gameplay owner");}
    public boolean started(){owned();return started;}public boolean reconnecting(){owned();return reconnectCount!=null;}public long mapEpoch(){owned();return mapEpoch;}public long modeEpoch(){owned();return modeEpoch;}public int cleanSlateResets(){owned();return cleanSlates;}public BotWorker.Status status(){owned();return worker.status();}
    public List<PlayerLife> players(){owned();return runtime.values().stream().map(Runtime::player).toList();}
    public Optional<BotMotor> motor(PlayerLife p){owned();var r=runtime.get(p.id());return r!=null&&r.player()==p?Optional.of(r.motor()):Optional.empty();}
    private int generation(PlayerLife p){var r=runtime.get(p.id());return r!=null&&r.player()==p?r.member.generation():-1;}
    private BotPerception.Actor actor(PlayerLife p){return new BotPerception.Actor(){public int id(){return p.id();}public Player snapshot(){return snapshots.player(p);}};}
    public void start(){start(null);}
    public void start(Integer count){owned();if(started)return;bind();started=true;worker.start(mapSnapshot);subscribe();int initial=count==null?populationMode.equals("backfill")?fillTarget:maxBots:count;for(int i=0;i<Math.max(0,initial);i++)if(add(null,null,null,null).isEmpty())break;}
    private void bind(){
        var replacement=Objects.requireNonNull(current.get());boolean changed=world!=replacement.world();if(match!=replacement)modeEpoch++;if(changed){mapEpoch++;world=replacement.world();mapSnapshot=new MapSnapshot(mapEpoch,world.topologyVersion(),world.sourceMapBytes(),replacement.modeCode(),replacement.mapName(),List.of(),world.sourceFormat(),maps==null?"":maps.toString()).withPrefabs(geometry);}match=replacement;topology=world.topologyVersion();snapshots=new HostedBotSnapshots(match,this::generation,p->motor(p).orElse(null));if(horde!=null)horde.close();horde=match.zombie().isEmpty()?null:new HostedBotHorde(match,()->mapEpoch,()->modeEpoch,p->motor(p).orElse(null),workClock,maps,match.mapName(),mapSnapshot.rawVxl());objectives=new HostedBotObjectives(match,()->horde==null?List.of():horde.orders(),()->horde==null?List.of():horde.refuge());
        perception=new BotPerception(new BotPerception.Services(){public List<BotPerception.Observer> observers(){return runtime.values().stream().map(r->r.observer).toList();}public List<BotPerception.Actor> players(){return match.lives().players().stream().map(HostedBotDirector.this::actor).toList();}public List<Entity> entities(){long before=snapshots.entityOverflow();var result=snapshots.entities();host.telemetry().ifPresent(t->t.metrics().add(net.battlespades.service.RuntimeMetrics.Counter.bot_perception_entity_overflow,snapshots.entityOverflow()-before));return result;}public List<Objective> objectives(){return objectives.snapshot();}public Map<String,Object> community(){return Map.of();}public void footsteps(List<BotPerception.Actor> ignored,double now){var rows=match.lives().players().stream().map(p->{var physics=p.physicsState().orElse(null);int movement=p.motion().snapshot().movement();return new FootstepPlayer(p.id(),p.team(),p.alive(),p.spawned(),physics!=null&&!physics.airborne(),(movement&32)!=0,(movement&64)!=0,(movement&128)!=0,physics==null?new Vector(0,0,0):physics.velocity(),p.position());}).toList();hearing.footsteps(rows,now);}public List<Stimulus> stimuli(BotPerception.Observer observer,double now){var r=runtime.get(observer.actor.id());return r==null?List.of():hearing.perceive(r.player().position(),now,r.random,24,r.player().id(),r.player().team());}public long mapEpoch(){return mapEpoch;}public long modeEpoch(){return modeEpoch;}public long topology(){return topology;}public String mode(){return match.modeCode();}public String phase(){return objectives.phase();}public String behavior(){return settings.behavior();}public boolean friendlyMischief(){return settings.friendlyMischief();}public void submit(Perception frame){frameId=frame.frameId();worker.submit(frame);}},settings.perceptionHz(),settings.mainThreadBudget(),workClock);perception.frameId(frameId);
        population=new BotPopulation(populationSettings(),new BotPopulation.Services(){public List<BotPopulation.Player> players(){return match.lives().players().stream().map(HostedBotDirector.this::populationPlayer).toList();}public int loadingReservations(){return Math.max(0,host.occupiedSlots()-match.lives().players().size());}public boolean ownsPopulation(){return false;}public boolean reconnecting(){return reconnectCount!=null;}public boolean add(){return HostedBotDirector.this.add(null,null,null,null).isPresent();}public boolean remove(BotPopulation.Player p,boolean force){var r=runtime.get(p.id());return r!=null&&r.member.generation()==p.generation()&&HostedBotDirector.this.remove(r.player(),force,true);}public boolean retireSafe(BotPopulation.Player p){var r=runtime.get(p.id());return r!=null&&match.botRetireSafe(r.player());}public int retireRank(BotPopulation.Player p){return match.zombie().isPresent()&&p.team()!=2?1:0;}});match.friendlyPaths(this::friendlyPaths);
    }
    private void subscribe(){unsubscribe();changes=world.observeCommits(c->{topology=Math.max(topology,c.version());worker.publish(new VoxelChange(c.cell().x(),c.cell().y(),c.cell().z(),c.solid(),c.color(),c.health()),mapEpoch,topology);},error->match.failure("bot terrain publication",error));lights=world.observeStaticLights((cell,color)->worker.publish(new VoxelChange(cell.x(),cell.y(),cell.z(),true,color,0),mapEpoch,topology),error->match.failure("bot light publication",error));publishLights();}
    private void publishLights(){for(var e:world.staticLightCells().entrySet()){var c=e.getKey();worker.publish(new VoxelChange(c.x(),c.y(),c.z(),true,e.getValue(),0),mapEpoch,topology);}}
    private void unsubscribe(){if(changes!=null){changes.close();changes=null;}if(lights!=null){lights.close();lights=null;}}
    private BotPopulation.Player populationPlayer(PlayerLife p){var r=runtime.get(p.id());var intent=r==null?null:r.motor().state().intent();boolean visible=intent!=null&&intent.look()!=null&&intent.look().visible(),vip=match.vip().map(v->v.vip(p.team()).filter(q->q==p).isPresent()).orElse(false),zero=match.zombie().map(z->z.patientZeros().size()==1&&z.patientZeros().contains(p)).orElse(false);return new BotPopulation.Player(p.id(),generation(p),p.team(),p.selection().classId(),p.bot(),p.alive(),p.pickupId()!=null,visible,vip,zero);}
    private int balanced(){long a=match.lives().players().stream().filter(p->p.team()==2).count(),b=match.lives().players().stream().filter(p->p.team()==3).count();return a==b?runtime.size()%2==0?2:3:a<b?2:3;}
    private Integer chooseClass(int team,BotProfile profile,Integer requested){var counts=new HashMap<Integer,Integer>();for(var p:match.lives().players())if(p.team()==team)counts.merge(p.selection().classId(),1,Integer::sum);return BotPopulation.chooseClass(match.modeCode(),match.hardcore(),match.botClasses(team),counts,profile.classPreferences(),requested,randomRoster);}
    public Optional<PlayerLife> add(Integer team,String name,Integer classId,String difficulty){owned();if(!started||runtime.size()>=maxBots||host.occupiedSlots()>=host.playerLimit())return Optional.empty();int selectedTeam=match.botTeam(team!=null&&(team==2||team==3)?team:balanced());if(selectedTeam!=2&&selectedTeam!=3)return Optional.empty();var profile=profiles.create(difficulty==null?this.difficulty:difficulty);String allocated=profile.name();if(name!=null&&!name.isEmpty())profile=rename(profile,name.substring(0,Math.min(15,name.length())));Integer chosen=chooseClass(selectedTeam,profile,classId);if(chosen==null){profiles.release(allocated);return Optional.empty();}var selection=match.botSelection(selectedTeam,chosen,randomRoster);String display=PlayerNames.allocateBot(profile.name(),settings.namePrefix(),match.lives().players().stream().map(p->new PlayerNames.Existing(p.name(),match.admin(p))).toList());try{var member=roster.add(display,selectedTeam,selection);if(member.isEmpty()){profiles.release(allocated);return Optional.empty();}var r=new Runtime(member.get(),profile);runtime.put(r.player().id(),r);profileNames.put(r.player().id(),allocated);banter.register(r.player().id(),profile.name());return Optional.of(r.player());}catch(RuntimeException failure){profiles.release(allocated);throw failure;}}
    private final Map<Integer,String> profileNames=new HashMap<>();
    private static BotProfile rename(BotProfile p,String name){return new BotProfile(name,p.difficulty(),p.skill(),p.aggression(),p.caution(),p.teamwork(),p.creativity(),p.reactionTime(),p.trackingDelay(),p.turnSpeed(),p.turnAcceleration(),p.recoilControl(),p.burstDiscipline(),p.preferredRange(),p.aimNoise(),p.classPreferences());}
    public boolean safeToRetire(PlayerLife p){owned();var r=runtime.get(p.id());return r!=null&&r.player()==p&&population.safe(populationPlayer(p));}
    public boolean remove(PlayerLife p,boolean force,boolean notifyMode){owned();var r=runtime.get(p.id());if(r==null||r.player()!=p||!force&&!safeToRetire(p))return false;if(!roster.remove(r.member,notifyMode))return false;runtime.remove(p.id());pending.remove(p.id());profiles.release(profileNames.remove(p.id()));banter.forget(p.id());return true;}
    public boolean makeRoomForHuman(){owned();return started&&reconnectCount==null&&population.makeRoom();}
    private BotPopulation.Settings populationSettings(){return new BotPopulation.Settings(populationMode,fillTarget,maxBots,settings.reserveHumans(),host.playerLimit());}
    public void backfill(int target){owned();populationMode="backfill";fillTarget=Math.clamp(target,0,host.playerLimit());maxBots=Math.max(maxBots,fillTarget);requestPopulationRefresh();}
    public void manualPopulation(int additional){owned();populationMode="admin";maxBots=Math.max(maxBots,runtime.size()+Math.max(0,additional));requestPopulationRefresh();}
    public void difficulty(String value){owned();if(!Set.of("casual","normal","hard","mixed").contains(value))throw new IllegalArgumentException("Invalid bot difficulty");difficulty=value;}
    public void debug(boolean enabled){owned();debug=enabled;}
    public List<Map<String,Object>> debugSnapshot(String prefix){owned();if(!debug)return List.of();String wanted=prefix==null?"":prefix.toLowerCase(Locale.ROOT);var rows=new ArrayList<Map<String,Object>>();for(var r:runtime.values().stream().limit(32).toList()){if(!r.player().name().toLowerCase(Locale.ROOT).startsWith(wanted))continue;var i=r.motor().state().intent();var row=new LinkedHashMap<String,Object>();row.put("id",r.player().id());row.put("name",r.player().name());row.put("action",i==null?"idle":i.action().kind().code());row.put("affordance",i==null?"walk":i.movement().affordance().code());row.put("goal",i==null?null:i.debugGoal());row.put("path",i==null?List.of():i.debugPath());row.put("role",i==null?"idle":i.debugRole());rows.add(Collections.unmodifiableMap(row));}return List.copyOf(rows);}
    public String namePrefix(){owned();return settings.namePrefix();}
    public void requestPopulationRefresh(){owned();nextPopulation=0;population.settings(populationSettings());}
    public void update(double fixedDt){owned();if(!started||reconnectCount!=null)return;if(current.get()!=match)throw new IllegalStateException("Bot roster must be prepared before replacing its match");double now=match.monotonic();for(var r:List.copyOf(runtime.values()))if(!roster.current(r.member)){runtime.remove(r.player().id());pending.remove(r.player().id());profiles.release(profileNames.remove(r.player().id()));banter.forget(r.player().id());}
        boolean maintained=now>=nextPopulation;if(maintained){nextPopulation=now+1;worker.recoverIfStopped();population.maintain(now);releaseBanter(now);}double section=workClock.getAsDouble();for(var intent:worker.drain(12)){var r=runtime.get(intent.botId());if(r!=null)r.motor().accept(intent,mapEpoch,modeEpoch,topology,now);}timing("bots_intents",section);if(maintained)return;section=workClock.getAsDouble();boolean refreshed=perception.publishDue(now);timing("bots_perception",section);if(refreshed)return;section=workClock.getAsDouble();budget.reset();int phase=motorPhase;motorPhase=(motorPhase+1)%6;for(var r:runtime.values()){classLifetime(r);if(r.player().id()%6!=phase)continue;double dt=r.lastMotor>0?Math.min(.25,Math.max(fixedDt,now-r.lastMotor)):fixedDt*6;r.lastMotor=now;r.hosted.tick(now,dt);}timing("bots_motors",section);}
    private void timing(String name,double startedAt){double elapsed=(workClock.getAsDouble()-startedAt)*1000;host.telemetry().ifPresent(t->t.metrics().recordSubsystem(name,elapsed));}
    private void classLifetime(Runtime r){boolean alive=r.player().alive();if(r.wasAlive&&!alive&&--r.lives<=0){Integer chosen=chooseClass(r.player().team(),r.profile,null);if(chosen!=null){match.botClassChange(r.player(),match.botSelection(r.player().team(),chosen,r.random));r.lives=2+r.random.below(4);}}r.wasAlive=alive;}
    public int drainActions(int limit){owned();if(reconnectCount!=null)return 0;int count=0;for(int id:pending.keySet().stream().limit(Math.max(0,limit)).toList()){var action=pending.remove(id);var r=runtime.get(id);if(r!=null&&r.motor()==action.motor()&&roster.current(r.member)&&r.motor().commit(action.action(),Math.max(action.at(),match.monotonic())))count++;}return count;}
    public void observePhysics(PlayerLife p,double now){owned();var r=runtime.get(p.id());if(r!=null&&r.player()==p)r.hosted.observePhysics(now);}
    public void stimulus(StimulusKind kind,Vector at,int source,int team,double radius,double lifetime){owned();if(started)hearing.publish(kind,at,source,team,radius,lifetime,match.monotonic());}
    public void killed(PlayerLife victim,PlayerLife killer,int type){owned();if(!started||killer==null)return;stimulus(StimulusKind.DEATH,victim.position(),killer.id(),victim.team(),BotStimulusBus.HEARING_DISTANCE,1);if(!settings.chatter()||victim!=killer&&victim.team()==killer.team())return;double distance=Math.sqrt(Math.pow(victim.position().x()-killer.position().x(),2)+Math.pow(victim.position().y()-killer.position().y(),2)+Math.pow(victim.position().z()-killer.position().z(),2));banter.killed(match.monotonic(),killer.id(),victim.id(),killer.name(),victim.name(),Math.toIntExact(match.binding().row(killer).killStreak),distance,type==2,Set.of(3,4,5,14,15,22,23,19).contains(type));}
    public void phase(String kind,double delay){owned();if(started&&settings.chatter())banter.phase(match.monotonic()+Math.max(0,delay),kind);}
    private void releaseBanter(double now){if(!settings.chatter())return;var busy=new HashSet<Integer>();for(var r:runtime.values())if(r.player().alive()&&r.motor().state().locked(now-2.55))busy.add(r.player().id());for(var line:banter.due(now,busy))if(runtime.containsKey(line.playerId()))host.broadcast(new SimplePackets.ChatMessage(line.playerId(),0,line.text()),Delivery.RELIABLE);}
    public void updateSkill(double now){owned();if(!started)return;var humans=match.lives().players().stream().map(p->{var row=match.binding().row(p);return new BotSkillBalancer.Human(p.team(),row.kills,row.deaths,p.bot());}).toList();var scores=new HashMap<Integer,Double>();for(var team:match.teams())scores.put(team.id,(double)team.score);var bots=runtime.values().stream().map(r->new BotSkillBalancer.Bot(new BotState.Observer(r.player().id(),r.member.generation()),r.player().team(),r.profile)).toList();var changes=skill.update(now,new BotSkillBalancer.Roster(humans,scores,true,match.mode().clock().ended),bots,new BotSkillBalancer.Settings(settings.skill().enabled(),difficulty,settings.skill().rate(),settings.skill().maxShift(),settings.skill().minEvents(),settings.skill().deadband()));for(var r:runtime.values()){r.profile=changes.get(new BotState.Observer(r.player().id(),r.member.generation()));r.observer.profile=r.profile;r.motor().profile(r.profile);}}
    public Set<BlockDamageModel.Cell> friendlyPaths(int team,int excluded){owned();var cells=new HashSet<BlockDamageModel.Cell>();for(var r:runtime.values()){var p=r.player();var intent=r.motor().state().intent();if(p.id()==excluded||p.team()!=team||!p.alive()||!p.spawned()||intent==null)continue;var d=intent.movement().direction();double length=Math.hypot(d.x(),d.y());if(length<=1e-6)continue;for(double distance:new double[]{.75,1.5,2.25}){int x=(int)Math.floor(p.position().x()+d.x()/length*distance),y=(int)Math.floor(p.position().y()+d.y()/length*distance),z=(int)Math.floor(p.position().z());cells.add(new BlockDamageModel.Cell(x,y,z));cells.add(new BlockDamageModel.Cell(x,y,z+1));}}return Set.copyOf(cells);}
    private void clearTimeline(){pending.clear();perception.reset();hearing=new BotStimulusBus();banter.reset();for(var r:runtime.values())r.motor().clear();if(horde!=null)horde.reset();}
    public void prepareTransition(){owned();if(!started||reconnectCount!=null)return;reconnectCount=runtime.size();clearTimeline();for(var p:players())remove(p,true,false);}
    private void reconnect(){int count=reconnectCount==null?0:reconnectCount;for(int i=0;i<count;i++){var p=add(null,null,null,null);if(p.isEmpty())break;match.scoreboard().playerScore(match.binding().row(p.get()),0);}reconnectCount=null;nextPopulation=match.monotonic()+1;population.settings(populationSettings());if(settings.cleanSlateGames()>0&&++games>=settings.cleanSlateGames()){worker.restart();cleanSlates++;games=0;}}
    public void rebind(){owned();if(!started)return;prepareTransition();unsubscribe();long previous=mapEpoch;bind();clearTimeline();if(mapEpoch!=previous)worker.publishMap(mapSnapshot);else worker.discardTimeline();subscribe();reconnect();phase("start",10);}
    public void resetAfterRestart(){owned();if(!started)return;prepareTransition();modeEpoch++;clearTimeline();worker.discardTimeline();reconnect();}
    public TeamBalancer.Bots balancing(){owned();return new TeamBalancer.Bots(){public boolean started(){return HostedBotDirector.this.started();}public boolean reconnecting(){return HostedBotDirector.this.reconnecting();}public List<PlayerLife> players(){return HostedBotDirector.this.players();}public boolean safeToRetire(PlayerLife p){return HostedBotDirector.this.safeToRetire(p);}public CompletionStage<Boolean> remove(PlayerLife p){return CompletableFuture.completedFuture(HostedBotDirector.this.remove(p,false,true));}public CompletionStage<Void> add(int team){HostedBotDirector.this.add(team,null,null,null);return CompletableFuture.completedFuture(null);}};}
    @Override public void close()throws IOException{if(Thread.currentThread()!=owner)throw new IllegalStateException("Bot director outside owner");if(closed)return;RuntimeException cleanup=null;for(var p:players())try{remove(p,true,true);}catch(RuntimeException failure){if(cleanup==null)cleanup=failure;else cleanup.addSuppressed(failure);}unsubscribe();if(horde!=null)horde.close();worker.close();if(cleanup!=null)throw cleanup;pending.clear();reconnectCount=null;started=false;host.botRoomForHuman(()->false);closed=true;}
}
